def migrate_processing_job_data(apps, schema_editor):
    """Migrate ProcessingJob data to Recording fields"""
    Recording = apps.get_model('recordings', 'Recording')
    
    # Skip if processing app doesn't exist (already migrated)
    try:
        ProcessingJob = apps.get_model('processing', 'ProcessingJob')
    except LookupError:
        print("\n=== ProcessingJob model not found (already migrated) ===")
        return
    
    print("\n=== Migrating ProcessingJob data to Recording ===")
    
    for job in ProcessingJob.objects.all():
        recording = job.recording
        recording.celery_task_id = job.celery_task_id
        recording.processing_progress = job.progress_percentage
        recording.processing_started_at = job.started_at
        recording.save(update_fields=['celery_task_id', 'processing_progress', 'processing_started_at'])
        print(f"  ✓ Migrated ProcessingJob for Recording {recording.id}")
    
    print(f"  Total: Migrated {ProcessingJob.objects.count()} ProcessingJobs")


